INSERT INTO SALESAPP.WHATSAPP_TEMPLATES (TEMPLATE_ID,TEMPLATE_NAME,TEMPLATE_BODY,VARIABLES,IS_ACTIVE) VALUES (1,'PAYMENT_RECEIPT','¡Hola {customer_name}! Confirmamos tu pago de ${amount} el día {payment_date}. Tu saldo restante es ${remaining_balance}. ¡Gracias por tu puntualidad! 🙏','customer_name,amount,payment_date,remaining_balance','1');
INSERT INTO SALESAPP.WHATSAPP_TEMPLATES (TEMPLATE_ID,TEMPLATE_NAME,TEMPLATE_BODY,VARIABLES,IS_ACTIVE) VALUES (2,'PAYMENT_REMINDER','Hola {customer_name}, te recordamos que tu próximo pago de ${amount} vence el {due_date}. ¡Contamos contigo! 😊','customer_name,amount,due_date','1');
INSERT INTO SALESAPP.WHATSAPP_TEMPLATES (TEMPLATE_ID,TEMPLATE_NAME,TEMPLATE_BODY,VARIABLES,IS_ACTIVE) VALUES (3,'LATE_PAYMENT_NOTICE','Estimado/a {customer_name}, detectamos que tienes {days_late} días de atraso en tu pago. Por favor comunícate con nosotros para regularizar tu situación. Saldo pendiente: ${remaining_balance}','customer_name,days_late,remaining_balance','1');
